fn crc(d: &[u8]) -> u32 { crc32fast::hash(d) }
#[derive(Clone)]
struct E { name: Vec<u8>, data: Vec<u8>, method: u16, flags: u16, crc: u32, cs: u32, us: u32, lx: Vec<u8>, cx: Vec<u8>, comment: Vec<u8>, made: u16, attrs: u32, date: u16, time: u16 }
fn e(name: &str, data: &[u8]) -> E { E { name: name.as_bytes().to_vec(), data: data.to_vec(), method: 0, flags: 0, crc: crc(data), cs: data.len() as u32, us: data.len() as u32, lx: vec![], cx: vec![], comment: vec![], made: (3<<8)|20, attrs: 0o100644<<16, date: 0x5021, time: 0x6000 } }
fn field(id: u16, body: &[u8]) -> Vec<u8> { let mut v = id.to_le_bytes().to_vec(); v.extend((body.len() as u16).to_le_bytes()); v.extend(body); v }
fn z64(us: u64, cs: u64) -> Vec<u8> { let mut b = us.to_le_bytes().to_vec(); b.extend(cs.to_le_bytes()); field(1, &b) }
fn lfh(o: &mut Vec<u8>, x: &E) {
    o.extend(b"PK\x03\x04"); o.extend(20u16.to_le_bytes()); o.extend(x.flags.to_le_bytes()); o.extend(x.method.to_le_bytes());
    o.extend(x.time.to_le_bytes()); o.extend(x.date.to_le_bytes()); o.extend(x.crc.to_le_bytes()); o.extend(x.cs.to_le_bytes()); o.extend(x.us.to_le_bytes());
    o.extend((x.name.len() as u16).to_le_bytes()); o.extend((x.lx.len() as u16).to_le_bytes()); o.extend(&x.name); o.extend(&x.lx);
}
fn cdh(o: &mut Vec<u8>, x: &E, off: u32) {
    o.extend(b"PK\x01\x02"); o.extend(x.made.to_le_bytes()); o.extend(20u16.to_le_bytes()); o.extend(x.flags.to_le_bytes()); o.extend(x.method.to_le_bytes());
    o.extend(x.time.to_le_bytes()); o.extend(x.date.to_le_bytes()); o.extend(x.crc.to_le_bytes()); o.extend(x.cs.to_le_bytes()); o.extend(x.us.to_le_bytes());
    o.extend((x.name.len() as u16).to_le_bytes()); o.extend((x.cx.len() as u16).to_le_bytes()); o.extend((x.comment.len() as u16).to_le_bytes());
    o.extend(0u16.to_le_bytes()); o.extend(0u16.to_le_bytes()); o.extend(x.attrs.to_le_bytes()); o.extend(off.to_le_bytes()); o.extend(&x.name); o.extend(&x.cx); o.extend(&x.comment);
}
fn eocd(o: &mut Vec<u8>, disk_n: u16, tot: u16, cd_sz: u32, cd_off: u32, comment: &[u8]) {
    o.extend(b"PK\x05\x06"); o.extend(0u16.to_le_bytes()); o.extend(0u16.to_le_bytes()); o.extend(disk_n.to_le_bytes()); o.extend(tot.to_le_bytes());
    o.extend(cd_sz.to_le_bytes()); o.extend(cd_off.to_le_bytes()); o.extend((comment.len() as u16).to_le_bytes()); o.extend(comment);
}
fn build(es: &[E]) -> Vec<u8> {
    let mut o = vec![]; let mut offs = vec![];
    for x in es { offs.push(o.len() as u32); lfh(&mut o, x); o.extend(&x.data); }
    let cs = o.len() as u32;
    for (x, off) in es.iter().zip(&offs) { cdh(&mut o, x, *off); }
    let sz = o.len() as u32 - cs;
    eocd(&mut o, es.len() as u16, es.len() as u16, sz, cs, b"");
    o
}
fn open(b: &[u8]) -> zip::result::ZipResult<ZipArchive<Cursor<Vec<u8>>>> { ZipArchive::new(Cursor::new(b.to_vec())) }
fn names(a: &ZipArchive<Cursor<Vec<u8>>>) -> Vec<String> { a.file_names().map(|s| s.to_string()).collect() }
fn tmpd(t: &str) -> std::path::PathBuf { let d = std::env::temp_dir().join(format!("p-{}-{}", t, std::process::id())); let _ = fs::remove_dir_all(&d); fs::create_dir_all(&d).unwrap(); d }
fn mode(p: &std::path::Path) -> String { match fs::symlink_metadata(p) { Ok(m) => format!("{:o}{}", m.permissions().mode(), if m.file_type().is_symlink() {" symlink"} else {""}), Err(e) => format!("ERR {e}") } }
fn rd(a: &mut ZipArchive<Cursor<Vec<u8>>>, n: &str) -> String { let mut v = vec![]; match a.by_name(n) { Ok(mut f) => { let s=f.size(); let c=f.compressed_size(); let r = f.read_to_end(&mut v); format!("size={s} csize={c} read={:?} data={:?}", r.map_err(|e| e.to_string()), String::from_utf8_lossy(&v[..v.len().min(60)])) } Err(e) => format!("open err {e:?}") } }
fn data_path() -> String { "/work/crate/tests/data".into() }
fn fx(n: &str) -> Vec<u8> { fs::read(format!("{}/{}", data_path(), n)).unwrap() }
fn aes_zip(content: &[u8]) -> Vec<u8> { let mut z = ZipWriter::new(Cursor::new(vec![])); z.start_file("a", O::default().compression_method(CM::Stored).with_aes_encryption(AesMode::Aes256, "pw")).unwrap(); z.write_all(content).unwrap(); z.finish().unwrap().into_inner() }
fn crypt_zip(content:&[u8])->Vec<u8>{ let mut z = ZipWriter::new(Cursor::new(vec![])); z.start_file("a", O::default().compression_method(CM::Stored).with_deprecated_encryption(b"pw")).unwrap(); z.write_all(content).unwrap(); z.finish().unwrap().into_inner() }
fn append_noop(b: &[u8]) -> zip::result::ZipResult<Vec<u8>> { let z = ZipWriter::new_append(Cursor::new(b.to_vec()))?; Ok(z.finish()?.into_inner()) }
fn extract_show(b:&[u8], t:&str)->std::path::PathBuf{ let d=tmpd(t); let mut a=open(b).unwrap(); println!("extract={:?}", a.extract(&d)); d }

