fn symlink_entry(us: u64) -> Vec<u8> { let mut x = e("l", b"t"); x.attrs = 0o120777<<16; x.us=0xFFFFFFFF; x.cx=z64(us,1); x.cs=0xFFFFFFFF; x.crc=crc(b"t"); build(&[x]) }
