fn legacy(m:u16, us:u64)->Vec<u8>{ let mut x=e("l",b"\0\0\0\0\0\0\0\0"); x.method=m; x.us=0xFFFFFFFF; x.cx=z64(us,8); x.cs=0xFFFFFFFF; build(&[x]) }
fn t_legacy(m:u16, us:u64){ let b=legacy(m,us); let mut a=open(&b).unwrap(); let mut f=a.by_index(0).unwrap(); let mut v=vec![]; println!("{:?}", f.read_to_end(&mut v).map_err(|e|e.to_string())); }
struct Bits{o:Vec<u8>,acc:u32,n:u32}
impl Bits{fn new()->Self{Bits{o:vec![],acc:0,n:0}} fn put(&mut self,c:u32,w:u32){self.acc|=c<<self.n;self.n+=w;while self.n>=8{self.o.push(self.acc as u8);self.acc>>=8;self.n-=8;}} fn done(mut self)->Vec<u8>{if self.n>0{self.o.push(self.acc as u8);}self.o}}
fn t_shrink_stack(pairs:usize){ let mut w=Bits::new(); w.put(65,9); for _ in 0..pairs { w.put(256,9); w.put(2,9);} let d=w.done(); println!("payload {}",d.len()); let mut x=e("s",&d); x.method=1; x.us=100; x.crc=crc(b"A"); let b=build(&[x]); let mut a=open(&b).unwrap(); let mut f=a.by_index(0).unwrap(); let mut v=vec![]; println!("{:?}", f.read_to_end(&mut v).map_err(|e|e.to_string())); }
fn t_shrink8191(target:u32){
    // LZW: emit literals; each literal after first creates next free code. Then reference `target`.
    let mut w=Bits::new(); let mut size=9u32; let mut next=257u32; let mut out=vec![]; let mut lit=0u8; let mut prev:Option<u8>=None; let mut table:Vec<(u8,u8)>=vec![];
    // table[k] = code 257+k = (prev, first)
    while next<=target { // need to have defined entries up to target; entry `next` defined after one more code emitted
        let l = lit; lit=lit.wrapping_add(1);
        // bump code size as encoder: when the next code needs more bits
        w.put(l as u32,size); out.push(l);
        if let Some(p)=prev { next+=1; }
        prev=Some(l);
        while next>= (1<<size) && size<13 { w.put(256,size); w.put(1,size); size+=1; }
    }
    // emit target
    w.put(target,size);
    let n=out.len(); let e0=(target-257) as usize; out.push(out[e0]); out.push(out[e0+1]);
    let d=w.done(); let mut x=e("s",&d); x.method=1; x.us=out.len() as u32; x.crc=crc(&out); let b=build(&[x]); let mut a=open(&b).unwrap(); let mut f=a.by_index(0).unwrap(); let mut v=vec![]; let r=f.read_to_end(&mut v); println!("target={target} {:?} ok={}", r.map_err(|e|e.to_string()), v==out);
}
