// --- AES
fn patch_c(b:&mut Vec<u8>, new_cs:u32){ let p=b.windows(4).position(|w|w==b"PK\x01\x02").unwrap(); b[p+20..p+24].copy_from_slice(&new_cs.to_le_bytes()); }
fn t_aes_truncate(){ let mut b=aes_zip(b"pay alice $100");
  // ctrl: tamper
  let ds=30+1+11; let mut t=b.clone(); t[ds+18]^=1; { let mut a=open(&t).unwrap(); let mut f=a.by_index_decrypt(0,b"pw").unwrap(); let mut v=vec![]; println!("control tamper {:?}",f.read_to_end(&mut v).map_err(|x|x.to_string())); }
  // layout: move EOCD/CD before data
  let a0=open(&b).unwrap(); let cdstart=a0.central_directory_start() as usize;
  let mut cs=[0u8;4]; let p=cdstart; cs.copy_from_slice(&b[p+20..p+24]); let cs=u32::from_le_bytes(cs) as usize;
  println!("cs={cs}");
  // entries: local hdr + data. New file: LFH + 18 header + CD + EOCD + ciphertext(flipped)(no auth)
  let hdr_end=ds+18; let ct=b[hdr_end..hdr_end+14].to_vec(); let mut ct2=ct.clone(); ct2[10]^=0x08;
  let mut o=b[..hdr_end].to_vec(); let cd=o.len(); let mut cdb=b[p..].to_vec(); // cd + eocd
  let eo=cdb.windows(4).position(|w|w==b"PK\x05\x06").unwrap(); cdb[eo+16..eo+20].copy_from_slice(&(cd as u32).to_le_bytes());
  let _=cdb; 
  o.extend(&cdb);
  // data does not directly follow header though -> need data right after header. So instead: data first? Put CD before data impossible as data_start fixed.
  println!("(see t_aes_truncate2)");
}
fn t_aes_truncate2(){ // Simple truncate: patch central cs past EOF so the Take doesn't stop; data then runs into CD/EOCD: keep trailing tampered? => use garbage-after-EOCD trick
  let b=aes_zip(b"pay alice $100"); let a0=open(&b).unwrap(); let cdstart=a0.central_directory_start() as usize; let eo=b.windows(4).rposition(|w|w==b"PK\x05\x06").unwrap();
  let cs=u32::from_le_bytes(b[cdstart+20..cdstart+24].try_into().unwrap()) as usize; println!("orig cs={cs}");
  // Layout: [LFH with 0 extra? ] Build: place CD+EOCD *before* LFH+data; LFH offset points after EOCD; file ends right after ciphertext with no auth code, EOCD tolerated w/ trailing data.
  let lfh_len=cdstart-cs; let lfh=b[..lfh_len].to_vec(); let body=b[lfh_len..lfh_len+cs-10].to_vec(); let mut body2=body.clone(); let n=body2.len(); body2[n-4]^=0x08;
  let cd=b[cdstart..eo].to_vec(); let cdlen=cd.len(); let mut o=cd; // CD at 0
  // patch offset of local header and cs
  let lfh_off=(cdlen+22) as u32; o[42..46].copy_from_slice(&lfh_off.to_le_bytes()); o[20..24].copy_from_slice(&((cs+1) as u32).to_le_bytes());
  eocd(&mut o,1,1,cdlen as u32,0,b""); o.extend(&lfh); o.extend(&body2);
  match open(&o){Ok(mut a)=>{ println!("offset {}",a.offset()); let mut f=a.by_index_decrypt(0,b"pw").unwrap(); let mut v=vec![]; let r=f.read_to_end(&mut v); println!("forged read {:?} {:?}",r.map_err(|x|x.to_string()),String::from_utf8_lossy(&v)); },Err(e)=>println!("open err {e:?}")}
}
fn t_aes_empty(){ let b=aes_zip(b""); let cdstart=open(&b).unwrap().central_directory_start() as usize; let cs=u32::from_le_bytes(b[cdstart+20..cdstart+24].try_into().unwrap()) as usize; println!("cs={cs}");
  let mut t=b.clone(); for i in 0..10 { t[cdstart-1-i]^=0xFF; } let mut a=open(&t).unwrap(); let mut f=a.by_index_decrypt(0,b"pw").unwrap(); let mut v=vec![]; println!("flipped auth read {:?}",f.read_to_end(&mut v).map_err(|x|x.to_string())); }
fn t_aes_underflow(){ let b=aes_zip(b"hello"); let mut t=b.clone(); patch_c(&mut t,4); let mut a=open(&t).unwrap(); println!("key {:?}",a.get_aes_verification_key_and_salt(0).map(|o|o.is_some()).map_err(|e|e.to_string())); let r=a.by_index_decrypt(0,b"pw"); match r {Ok(mut f)=>{let mut v=vec![];println!("{:?}",f.read_to_end(&mut v).map_err(|e|e.to_string()))},Err(e)=>println!("err {e:?}")}; 
   let mut t=b.clone(); patch_c(&mut t,20); let mut a=open(&t).unwrap(); let r=a.by_index_decrypt(0,b"pw"); match r {Ok(mut f)=>{let mut v=vec![];let r=f.read_to_end(&mut v); println!("cs=20 {:?} n={}",r.map_err(|e|e.to_string()),v.len())},Err(e)=>println!("err {e:?}")}; }
