// --- zip64 append
fn big_file()->fs::File{ let p=std::env::temp_dir().join(format!("big-{}",std::process::id())); let f=fs::OpenOptions::new().read(true).write(true).create(true).truncate(true).open(&p).unwrap(); fs::remove_file(&p).unwrap(); f }
fn t_z64_append(){ // entry placed at offset 5GiB: write hole then zip via ZipWriter
  let mut f=big_file(); let off=5u64<<30; f.seek(SeekFrom::Start(off)).unwrap();
  let mut z=ZipWriter::new(f); // writer starts at current pos
  z.start_file("after",O::default().compression_method(CM::Stored)).unwrap(); z.write_all(b"data5g").unwrap(); let mut f=z.finish().unwrap();
  { let mut a=ZipArchive::new(&mut f).unwrap(); println!("names {:?} ", a.file_names().collect::<Vec<_>>()); let mut e=a.by_name("after").unwrap(); let mut s=String::new(); println!("before {:?} {s}",e.read_to_string(&mut s).map_err(|e|e.to_string())); }
  let mut z=ZipWriter::new_append(f).unwrap(); z.start_file("new",O::default()).unwrap(); z.write_all(b"x").unwrap(); let mut f=z.finish().unwrap();
  match ZipArchive::new(&mut f){Ok(mut a)=>{ println!("names {:?}", a.file_names().collect::<Vec<_>>()); match a.by_name("after"){Ok(mut e)=>{let mut s=String::new();println!("after-append {:?} {s}",e.read_to_string(&mut s).map_err(|e|e.to_string()));},Err(e)=>println!("after-append by_name err {e:?}")};},Err(e)=>println!("reopen err {e:?}")}
}
