fn t_raw_crypto(){ let b=crypt_zip(b"secret content"); let mut z=ZipWriter::new(Cursor::new(vec![])); {let mut a=open(&b).unwrap(); z.raw_copy_file(a.by_index_raw(0).unwrap()).unwrap();} let o=z.finish().unwrap().into_inner(); let mut a=open(&o).unwrap(); println!("enc={}",a.by_index_raw(0).unwrap().encrypted()); println!("{}",rd(&mut a,"a")); match a.by_name_decrypt("a",b"pw"){Ok(mut f)=>{let mut v=vec![];println!("dec {:?}",f.read_to_end(&mut v).map_err(|e|e.to_string()))},Err(e)=>println!("{e:?}")}; }
