struct V{files:usize,meta:usize,ds:bool} impl ZipStreamVisitor for V{fn visit_file<R:Read>(&mut self,f:&mut ZipFile<'_,R>)->zip::result::ZipResult<()>{self.files+=1; if self.ds {println!("data_start {}",f.data_start());} Ok(())} fn visit_additional_metadata(&mut self,_:&ZipStreamFileMetadata)->zip::result::ZipResult<()>{self.meta+=1;Ok(())}}
