struct FailRead{inner:Cursor<Vec<u8>>,fail_from:u64} impl Read for FailRead{fn read(&mut self,b:&mut [u8])->io::Result<usize>{ if self.inner.position()>=self.fail_from && self.inner.position()<self.fail_from+100 {return Err(io::Error::new(io::ErrorKind::PermissionDenied,"denied"));} self.inner.read(b)}} impl Seek for FailRead{fn seek(&mut self,p:SeekFrom)->io::Result<u64>{self.inner.seek(p)}}
