fn t_quad(k:usize){ // k fake EOCDs in trailing area pointing at CD with count too high
  let base=build(&[e("a",b"x")]); let cd=open(&base).unwrap().central_directory_start() as u32; let mut o=base[..base.len()-22].to_vec(); // many CD entries
  let mut cdb=vec![]; let x=e("a",b"x");
  let n=k; for i in 0..n { let mut y=x.clone(); y.name=format!("{i:06}").into_bytes(); cdh(&mut cdb,&y,0);} let start=o.len(); o.truncate(cd as usize); let cdoff=o.len(); o.extend(&cdb); let cdsz=cdb.len() as u32; for _ in 0..k { eocd(&mut o,(n+1) as u16,(n+1) as u16,cdsz,cdoff as u32,b""); }
  let t=std::time::Instant::now(); let r=open(&o); println!("k={k} size={} t={:?} {:?}",o.len(),t.elapsed(),r.map(|a|a.len()).map_err(|e|e.to_string())); }
fn t_overlap(n:usize){ let mut es=vec![]; for i in 0..n { es.push(e(&format!("{i:06}"),b"x")); } let b=build_many(&es); let mut a=open(&b).unwrap(); let t=std::time::Instant::now(); println!("n={n} {:?} {:?}",a.has_overlapping_files().map_err(|e|e.to_string()),t.elapsed()); }
fn build_many(es:&[E])->Vec<u8>{ let mut o=vec![];let mut off=vec![]; for x in es{off.push(o.len() as u32);lfh(&mut o,x);o.extend(&x.data);} let cs=o.len() as u32; for(x,f) in es.iter().zip(&off){cdh(&mut o,x,*f);} let sz=o.len() as u32-cs; let n=es.len(); if n>=65535 { let p=o.len() as u64; o.extend(b"PK\x06\x06"); o.extend(44u64.to_le_bytes()); o.extend(45u16.to_le_bytes()); o.extend(45u16.to_le_bytes()); o.extend(0u32.to_le_bytes()); o.extend(0u32.to_le_bytes()); o.extend((n as u64).to_le_bytes()); o.extend((n as u64).to_le_bytes()); o.extend((sz as u64).to_le_bytes()); o.extend((cs as u64).to_le_bytes()); o.extend(b"PK\x06\x07"); o.extend(0u32.to_le_bytes()); o.extend(p.to_le_bytes()); o.extend(1u32.to_le_bytes()); eocd(&mut o,0xFFFF,0xFFFF,sz,cs,b""); } else { eocd(&mut o,n as u16,n as u16,sz,cs,b""); } o }
