fn t_crypto_date(){ // hand-encrypt with data descriptor and date 0 vs valid
  fn enc(pw:&[u8],pt:&[u8],check:u8)->Vec<u8>{ let mut k=[0x12345678u32,0x23456789,0x34567890]; let t:Vec<u32>=(0..256u32).map(|i|{let mut c=i;for _ in 0..8{c=if c&1!=0{0xEDB88320^(c>>1)}else{c>>1};}c}).collect(); fn up(k:&mut [u32;3],b:u8,t:&[u32]){k[0]=(k[0]>>8)^t[((k[0]^b as u32)&0xff) as usize];k[1]=(k[1].wrapping_add(k[0]&0xff)).wrapping_mul(134775813).wrapping_add(1);k[2]=(k[2]>>8)^t[((k[2]^(k[1]>>24))&0xff) as usize];} for &b in pw{up(&mut k,b,&t);} let mut o=vec![]; let mut hdr=[0u8;12]; hdr[11]=check; for &b in hdr.iter().chain(pt.iter()){ let tmp=(k[2]|2)&0xffff; let ks=((tmp*(tmp^1))>>8) as u8; o.push(b^ks); up(&mut k,b,&t);} o }
  for (date,time) in [(0x5021u16,0x6000u16),(0u16,0x6000u16)]{ let pt=b"hello"; let ct=enc(b"pw",pt,(time>>8) as u8); let mut x=e("a",&ct); x.flags=9; x.crc=crc(pt); x.us=5; x.date=date; x.time=time; let b=build(&[x]); let mut a=open(&b).unwrap(); match a.by_index_decrypt(0,b"pw"){Ok(mut f)=>{let mut v=vec![];println!("date={date:#x} {:?} {:?}",f.read_to_end(&mut v).map_err(|e|e.to_string()),String::from_utf8_lossy(&v))},Err(e)=>println!("date={date:#x} err {e:?}")};} }
