fn t_count(){ let es=[e("a",b"1"),e("b",b"2")]; let b=build(&es); let eo=b.len()-22; let p=|d:u16,t:u16|{let mut c=b.clone(); c[eo+8..eo+10].copy_from_slice(&d.to_le_bytes()); c[eo+10..eo+12].copy_from_slice(&t.to_le_bytes()); c}; for (d,t) in [(0,2),(1,2),(2,3),(3,3),(1,1)]{ let c=p(d,t); fs::write(format!("/work/tmp/cnt_{d}_{t}.zip"),&c).unwrap(); println!("disk={d} tot={t} {:?}",open(&c).map(|a|names(&a)).map_err(|e|e.to_string())); } let mut es=vec![]; for i in 0..65537 { es.push(e(&format!("{i:06}"),b"")); } let mut o=vec![];let mut off=vec![]; for x in &es{off.push(o.len() as u32);lfh(&mut o,x);} let cs=o.len() as u32; for(x,f) in es.iter().zip(&off){cdh(&mut o,x,*f);} let sz=o.len() as u32-cs; eocd(&mut o,1,1,sz,cs,b""); println!("wrapped len {:?}",open(&o).map(|a|a.len()).map_err(|e|e.to_string())); fs::write("/work/tmp/cnt_wrap.zip",&o).unwrap(); }
