struct Flaky{inner:Cursor<Vec<u8>>,left:i64} impl Write for Flaky{fn write(&mut self,b:&[u8])->io::Result<usize>{ if self.left<=0 {return Err(io::Error::other("fail"));} let n=b.len().min(self.left as usize); self.left-=n as i64; self.inner.write(&b[..n])} fn flush(&mut self)->io::Result<()>{Ok(())}} impl Seek for Flaky{fn seek(&mut self,p:SeekFrom)->io::Result<u64>{self.inner.seek(p)}}
