fn t_xz_index(){ // xz stream header + index indicator with record count 2^56
  let hdr=[0xFD,b'7',b'z',b'X',b'Z',0,0,4]; let flags_crc=crc(&[0,4]); let mut s=hdr.to_vec(); s.extend(flags_crc.to_le_bytes()); s.push(0); // index indicator
  let mut n=1u64<<56; while n>=0x80 { s.push((n as u8&0x7f)|0x80); n>>=7;} s.push(n as u8); s.extend([0u8;64]);
  let mut x=e("x",&s); x.method=95; x.us=1; let b=build(&[x]); let mut a=open(&b).unwrap(); let mut f=a.by_index(0).unwrap(); let mut v=vec![]; println!("{:?}",f.read_to_end(&mut v).map_err(|e|e.to_string())); }
fn t_huff(seed:u64,iters:u64){ let b=fx("legacy/implode.zip"); let a0=open(&b).unwrap(); let mut s=seed; for it in 0..iters { let mut c=b.clone(); for _ in 0..4 { s^=s<<13; s^=s>>7; s^=s<<17; let p=(s as usize)%c.len().min(1300); s^=s<<13; s^=s>>7; s^=s<<17; c[p]=s as u8; } if let Ok(mut a)=open(&c){ for i in 0..a.len(){ if let Ok(mut f)=a.by_index(i){ let mut v=vec![]; let _=f.read_to_end(&mut v);} } } } println!("done"); }
