struct CountR{inner:Cursor<Vec<u8>>,reads:u64,seeks:u64} impl Read for CountR{fn read(&mut self,b:&mut [u8])->io::Result<usize>{self.reads+=1;self.inner.read(b)}} impl Seek for CountR{fn seek(&mut self,p:SeekFrom)->io::Result<u64>{self.seeks+=1;self.inner.seek(p)}}
