struct FailN{inner:Cursor<Vec<u8>>,at:u64,left:i32} impl Read for FailN{fn read(&mut self,b:&mut [u8])->io::Result<usize>{ if self.inner.position()==self.at { self.left-=1; if self.left<=0 {return Err(io::Error::new(io::ErrorKind::PermissionDenied,"denied"));} } self.inner.read(b)}} impl Seek for FailN{fn seek(&mut self,p:SeekFrom)->io::Result<u64>{self.inner.seek(p)}}
